edits.replacement:
token_ptr->token_id = INITIAL_STATE;
stream_ptr->stream_ind = START;
unget_char(ch, tstream_ptr->ch_stream);
token_ind--;
return(token_ptr);

cu_state = INITIAL_STATE;
ch = get_char(tstream_ptr->ch_stream);
token_str[token_ind++] = ch;
next_st = next_state(cu_state, ch);
if (next_st == -1) {
    return(error_or_eof_case(...));
}

for(start=0;ind<=token_ind;++start) {
    if(ind >= token_ind) break;
    token_str[start] = token_str[ind++];
}
token_str[start] = '\0';
